def f(g):
    # detect separator rows/cols
    H,W=len(g),len(g[0])
    hseps=[i for i,r in enumerate(g) if all(x==r[0] and x!=g[0][0] for x in r)]
    vseps=[j for j in range(W) if all(r[j]!=g[0][0] and r[j]==g[i][j] for i in range(H))]
    sepv=g[hseps[0]][0]
    hlines=[0]+hseps+[H]; vlines=[0]+vseps+[W]
    regs=[]
    for a,b in zip(hlines,hlines[1:]):
        for c,d in zip(vlines,vlines[1:]):
            regs.append((a,b,c,d))
    out=[[g[i][j] for j in range(W)] for i in range(H)]
    for a,b,c,d in regs:
        cnt={}
        for i in range(a,b):
            for j in range(c,d):
                if g[i][j]!=sepv:
                    cnt[g[i][j]]=cnt.get(g[i][j],0)+1
        minority=min(cnt,key=cnt.get); mcnt=cnt[minority]
        maj=max(cnt,key=cnt.get)
        if mcnt>=2:
            for i in range(a,b):
                for j in range(c,d):
                    if g[i][j]==sepv or g[i][j]==maj:
                        out[i][j]=minority
    return out
