def f(g):
    H,W=len(g),len(g[0])
    cc=Counter(x for r in g for x in r)
    dom=cc.most_common(1)[0][0]
    hsep=[i for i,r in enumerate(g) if len(set(r))==1 and r[0]!=dom]
    vsep=[j for j in range(W) if all(r[j]==g[0][j] for r in g) and g[0][j]!=dom]
    hs=[0]+hsep+[H]; vs=[0]+vsep+[W]
    out=[row[:] for row in g]
