    infos=[]
    for a,b in zip(hs,hs[1:]):
        for c,d in zip(vs,vs[1:]):
            cnt=Counter()
            for i in range(a,b):
                for j in range(c,d):
                    v=g[i][j]
                    if v==dom: continue
                    cnt[v]=cnt.get(v,0)+1
            if not cnt: continue
            items=sorted(cnt.items(), key=lambda kv:kv[1])
            minor=items[0][0]; mc=items[0][1]
