import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(g):
    H,W=len(g),len(g[0])
    cc=Counter(x for r in g for x in r); bg=cc.most_common(1)[0][0]
    hs=[i for i,r_ in enumerate(g) if len(set(r_))==1 and r_[0]!=bg]
    vs=[j for j in range(W) if all(g[i][j]==g[0][j] for i in range(H)) and g[0][j]!=bg]
    sb=set(g[h][0] for h in hs)|set(g[0][v] for v in vs)
    marks=[k for k,n in cc.items() if k not in (bg,sb)]
    mc=min(marks,key=lambda k:cc[k])
    out=[r[:] for r in g]
    rbands=[(0,hs[0])] + [(hs[i],hs[i+1]) for i in range(len(hs)-1)] + [(hs[-1],H)] if hs else [(0,H)]
    cbands=[(0,vs[0])] + [(vs[i],vs[i+1]) for i in range(len(vs)-1)] + [(vs[-1],W)] if vs else [(0,W)]
    for a,b in rbands:
        cnts=[]
        for c,d in cbands:
            n=sum(1 for i in range(a,b) for j in range(c,d) if g[i][j]==mc)
            cnts.append(n)
        mx=max(cnts)
        for idx,(c,d) in enumerate(cbands):
            if cnts[idx]==mx and cnts[idx]>0:
                for i in range(a,b):
                    for j in range(c,d):
                        if g[i][j] not in sb: out[i][j]=mc
    return out
for p in [1,2]:
